import 'package:fsm2/fsm2.dart';

void main() {
  final machine = StateMachine.create((g) => g
    ..initialState(Solid())
    ..state<Solid>((b) => b..on<OnMelted, Liquid>(sideEffect: (e) => print('Melted')))
    ..state<Liquid>((b) => b..onEnter((s, e) => print('Enter Liquid'))));
  machine.applyEvent(OnMelted());
}
